package org.brightstats.desktop;
import java.util.*;
import com.google.gson.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Window;
import org.brightstats.data.HigherOrderInput;
import org.brightstats.stats.*;
final class HigherOrderDialog {
    record Settings(HigherOrderPls.Specification specification,Bootstrap.Options bootstrap){Settings{Objects.requireNonNull(specification);Objects.requireNonNull(bootstrap);}}
    private final Dialog<Settings> dialog=new Dialog<>();private final ListView<String> dimensions=new ListView<>();private final TextField name=new TextField("Higher-order"),samples=new TextField(),seed=new TextField(),confidence=new TextField();
    private final ComboBox<PlsSem.Mode> mode=new ComboBox<>();private final ComboBox<PlsSem.MeasurementType> measurement=new ComboBox<>();private final ComboBox<BootstrapIntervals.Method> interval=new ComboBox<>();
    private final TextArea advanced=new TextArea(),preview=new TextArea();private final TabPane tabs=new TabPane();private final Label error=new Label();private final int width;private final List<PlsSem.Block> blocks;private final List<PlsSem.Edge> edges;private final PlsSem.Options options;private Settings result;
    HigherOrderDialog(Window owner,int width,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,Settings previous,boolean resampling){
        if(blocks.size()<2)throw new IllegalArgumentException("Create at least two measured lower-order constructs.");this.width=width;this.blocks=List.copyOf(blocks);this.edges=List.copyOf(edges);this.options=options;dialog.initOwner(owner);dialog.setTitle(resampling?"Higher-order two-stage bootstrap":"Explicit two-stage higher-order PLS");dialog.setResizable(true);var names=blocks.stream().map(PlsSem.Block::name).toList();String candidate="Higher-order";int suffix=2;while(names.contains(candidate))candidate="Higher-order "+suffix++;name.setText(candidate);dimensions.getItems().setAll(names);dimensions.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);dimensions.getSelectionModel().selectIndices(0,1);dimensions.setPrefHeight(160);mode.getItems().setAll(PlsSem.Mode.values());mode.setValue(PlsSem.Mode.B);measurement.getItems().setAll(PlsSem.MeasurementType.values());measurement.setValue(PlsSem.MeasurementType.FORMATIVE);var boot=previous==null?new Bootstrap.Options(5000,42,.95):previous.bootstrap();samples.setText(Integer.toString(boot.samples()));seed.setText(Long.toString(boot.seed()));confidence.setText(Double.toString(boot.confidence()));interval.getItems().setAll(BootstrapIntervals.Method.PERCENTILE,BootstrapIntervals.Method.BCA);interval.setValue(boot.interval()==BootstrapIntervals.Method.BCA?BootstrapIntervals.Method.BCA:BootstrapIntervals.Method.PERCENTILE);
        GridPane builder=new GridPane();builder.setHgap(14);builder.setVgap(8);builder.addRow(0,UiAppearance.label("Higher-order name"),name);builder.addRow(1,UiAppearance.label("Lower-order dimensions (Ctrl-click)"),dimensions);builder.addRow(2,UiAppearance.label("Higher-order measurement"),measurement);builder.addRow(3,UiAppearance.label("Higher-order weight mode"),mode);preview.setEditable(false);preview.setPrefRowCount(8);Button refresh=UiAppearance.button("Preview stage-two model");refresh.setOnAction(event->preview());VBox basic=new VBox(8,builder,refresh,preview);basic.setPadding(new Insets(12));advanced.setPrefRowCount(18);advanced.setText(new GsonBuilder().setPrettyPrinting().create().toJson(previous==null?build():previous.specification()));Button copy=UiAppearance.button("Replace with builder specification");copy.setOnAction(event->{try{advanced.setText(new GsonBuilder().setPrettyPrinting().create().toJson(build()));error.setText("");}catch(RuntimeException problem){error.setText(problem.getMessage());}});Label schema=UiAppearance.label("Full specification: retained contains first-stage indices; higherOrder lists {name,lowerOrder,mode,measurementType,initialWeights}; edges use stage-two indices (retained first, then higher-order definitions); options controls stage-two PLS. Multiple higher-order constructs are supported.");schema.setWrapText(true);VBox custom=new VBox(8,schema,copy,advanced);custom.setPadding(new Insets(12));Tab basicTab=new Tab("Build one higher-order construct",basic),customTab=new Tab("Full specification",custom);basicTab.setClosable(false);customTab.setClosable(false);tabs.getTabs().addAll(basicTab,customTab);if(previous!=null)tabs.getSelectionModel().select(customTab);
        GridPane resample=new GridPane();resample.setHgap(14);resample.setVgap(8);resample.addRow(0,UiAppearance.label("Bootstrap attempts"),samples);resample.addRow(1,UiAppearance.label("Seed"),seed);resample.addRow(2,UiAppearance.label("Confidence (0–1)"),confidence);resample.addRow(3,UiAppearance.label("Standard case interval"),interval);for(var node:List.of(samples,seed,confidence,interval))node.setDisable(!resampling);Label guidance=UiAppearance.label("Stage one estimates lower-order scores from the current declared model. A first-stage repeated-indicator HOC and its LOC connections support embedded two-stage estimation. Give the final HOC a distinct name from its stage-one counterpart. Stage two uses the selected scores as higher-order indicators; other constructs retain their raw indicators. Builder connections collapse the current graph: inspect the preview, or edit the full specification. Both stages are refitted in bootstrap. Isolated Mode B weights are initial-score definitions, not identified structural weights.");guidance.setWrapText(true);error.setWrapText(true);error.setStyle("-fx-text-fill:#a02020");VBox content=new VBox(10,guidance,tabs,resample,error);content.setPadding(new Insets(12));content.setPrefWidth(790);ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefViewportHeight(720);dialog.getDialogPane().setContent(scroll);ButtonType run=new ButtonType(resampling?"Bootstrap":"Calculate",ButtonBar.ButtonData.OK_DONE);dialog.getDialogPane().getButtonTypes().addAll(run,ButtonType.CANCEL);dialog.getDialogPane().lookupButton(run).addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{result=resolve();error.setText("");}catch(RuntimeException problem){error.setText(problem.getMessage());event.consume();}});dialog.setResultConverter(button->button==run?result:null);preview();
    }
    private HigherOrderPls.Specification build(){int[] selected=dimensions.getSelectionModel().getSelectedIndices().stream().mapToInt(Integer::intValue).toArray();Set<Integer> consumed=new HashSet<>();for(int index:selected)consumed.add(index);int[] retained=java.util.stream.IntStream.range(0,blocks.size()).filter(index->!consumed.contains(index)).toArray();int[] mapping=new int[blocks.size()];for(int j=0;j<retained.length;j++)mapping[retained[j]]=j;for(int index:selected)mapping[index]=retained.length;Set<PlsSem.Edge> collapsed=new LinkedHashSet<>();for(var edge:edges)if(mapping[edge.source()]!=mapping[edge.target()])collapsed.add(new PlsSem.Edge(mapping[edge.source()],mapping[edge.target()]));return new HigherOrderPls.Specification(retained,List.of(new HigherOrderPls.Dimension(name.getText().trim(),selected,mode.getValue(),measurement.getValue(),null)),new ArrayList<>(collapsed),options);}
    private void preview(){try{var specification=build();var prepared=HigherOrderPls.stageTwoBlocks(width,blocks,edges,specification);StringBuilder text=new StringBuilder("Stage-two indices:\n");for(int j=0;j<prepared.size();j++)text.append(j).append(" : ").append(prepared.get(j).name()).append('\n');text.append("\nConnections:\n");for(var edge:specification.edges())text.append(prepared.get(edge.source()).name()).append(" → ").append(prepared.get(edge.target()).name()).append('\n');if(specification.edges().isEmpty())text.append("No structural paths; inspect measurement identification.\n");preview.setText(text.toString());error.setText("");}catch(RuntimeException problem){preview.setText(problem.getMessage());}}
    private Settings resolve(){var specification=tabs.getSelectionModel().getSelectedIndex()==1?HigherOrderInput.specification(JsonParser.parseString(advanced.getText())):build();HigherOrderPls.validate(width,blocks,edges,specification);return new Settings(specification,new Bootstrap.Options(Integer.parseInt(samples.getText().trim()),Long.parseLong(seed.getText().trim()),Double.parseDouble(confidence.getText().trim()),interval.getValue(),RegressionBootstrap.Convention.STANDARD,true));}
    static Optional<Settings> show(Window owner,int width,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,Settings previous,boolean resampling){return new HigherOrderDialog(owner,width,blocks,edges,options,previous,resampling).dialog.showAndWait();}
    static Settings smokeTest(Window owner,int width,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options){var probe=new HigherOrderDialog(owner,width,blocks,edges,options,null,true);Button run=(Button)probe.dialog.getDialogPane().lookupButton(probe.dialog.getDialogPane().getButtonTypes().getFirst());javafx.application.Platform.runLater(()->{try{probe.dimensions.getSelectionModel().clearSelection();probe.dimensions.getSelectionModel().select(0);run.fire();if(!probe.dialog.isShowing()||probe.error.getText().isBlank())throw new AssertionError("Single higher-order dimension accepted");probe.dimensions.getSelectionModel().select(1);probe.samples.setText("29");run.fire();if(!probe.dialog.isShowing()||probe.error.getText().isBlank())throw new AssertionError("Invalid higher-order attempts accepted");probe.samples.setText("40");probe.confidence.setText("1");run.fire();if(!probe.dialog.isShowing()||probe.error.getText().isBlank())throw new AssertionError("Invalid higher-order confidence accepted");probe.confidence.setText(".95");run.fire();}catch(Throwable problem){probe.dialog.close();throw problem;}});return probe.dialog.showAndWait().orElseThrow(()->new AssertionError("Higher-order settings rejected valid input"));}
}
